31	import org.springframework.samples.petclinic.rest.advice.DuplicateHouseholdException;
32	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
33	import org.springframework.samples.petclinic.rest.api.OwnersApi;
34	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
35	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.PetDto;
37	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.VisitDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
40	import org.springframework.samples.petclinic.service.ClinicService;
41	import org.springframework.samples.petclinic.util.AddressNormalizer;
42	import org.springframework.samples.petclinic.util.HouseholdNormalizer;
43	import org.springframework.samples.petclinic.util.TelephoneNormalizer;
44	import org.springframework.security.access.prepost.PreAuthorize;
45	import org.springframework.web.bind.annotation.CrossOrigin;
46	import org.springframework.web.bind.annotation.RequestMapping;
47	import org.springframework.web.bind.annotation.RestController;
48	import org.springframework.web.util.UriComponentsBuilder;
49	
50	import jakarta.transaction.Transactional;
51	
52	/**
53	 * @author Vitaliy Fedoriv
54	 */
55	
56	@RestController
57	@CrossOrigin(exposedHeaders = "errors, content-type")
58	@RequestMapping("/api")
59	public class OwnerRestControllerV1 implements OwnersApi {
60	
61	    private final ClinicService clinicService;
62	
63	    private final OwnerMapper ownerMapper;
64	
65	    private final PetMapper petMapper;
66	
67	    private final VisitMapper visitMapper;
68	
69	    private final TelephoneNormalizer telephoneNormalizer;
70	
71	    private final HouseholdNormalizer householdNormalizer;
72	
73	    private final AddressNormalizer addressNormalizer;
74	
75	    public OwnerRestControllerV1(ClinicService clinicService,
76	                                 OwnerMapper ownerMapper,
77	                                 PetMapper petMapper,
78	                                 VisitMapper visitMapper,
79	                                 TelephoneNormalizer telephoneNormalizer,
80	                                 HouseholdNormalizer householdNormalizer,
81	                                 AddressNormalizer addressNormalizer) {
82	        this.clinicService = clinicService;
83	        this.ownerMapper = ownerMapper;
84	        this.petMapper = petMapper;
85	        this.visitMapper = visitMapper;
86	        this.telephoneNormalizer = telephoneNormalizer;
87	        this.householdNormalizer = householdNormalizer;
88	        this.addressNormalizer = addressNormalizer;
89	    }
90	
91	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
92	    @Override
93	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
94	        Collection<Owner> owners;
95	        if (lastName != null) {
96	            owners = this.clinicService.findOwnerByLastName(lastName);
97	        } else {
98	            owners = this.clinicService.findAllOwners();
99	        }
100	        if (owners.isEmpty()) {
101	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
102	        }
103	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
104	    }
105	
106	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
107	    @Override
108	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
109	        Owner owner = this.clinicService.findOwnerById(ownerId);
110	        if (owner == null) {
111	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
112	        }
113	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
114	    }
115	
116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
119	        HttpHeaders headers = new HttpHeaders();
120	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
121	        normalizeOwnerFields(owner);
122	        // Reject creating an owner whose normalized telephone is already used by another owner.
123	        String normalizedTelephone = owner.getTelephone();
124	        if (isTelephoneInUse(normalizedTelephone)) {
125	            throw new DuplicateTelephoneException(
126	                "An owner with telephone " + normalizedTelephone + " already exists");
127	        }
128	        // Identify any existing owners who share a household (same last name and address,
129	        // compared case-insensitively with collapsed whitespace) with the owner being created.
130	        List<Owner> householdMembers = sameHouseholdOwners(owner.getLastName(), owner.getAddress());
131	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
132	        // Reject creating an owner who shares a household with an existing owner, unless the
133	        // request explicitly opts in with 'sharesHousehold' true.
134	        if (!sharesHousehold && !householdMembers.isEmpty()) {
135	            throw new DuplicateHouseholdException(
136	                "An owner with the same last name and address already exists");
137	        }
138	        // When opting in and joining an existing household, assign the new owner and every
139	        // existing member the same stable household identifier derived from the last name and
140	        // address, so all owners of the household share one 'householdId'.
141	        if (sharesHousehold && !householdMembers.isEmpty()) {
142	            String householdId = householdNormalizer.householdId(owner.getLastName(), owner.getAddress());
143	            owner.setHouseholdId(householdId);
144	            for (Owner member : householdMembers) {
145	                if (!householdId.equals(member.getHouseholdId())) {
146	                    member.setHouseholdId(householdId);
147	                    this.clinicService.saveOwner(member);
148	                }
149	            }
150	        }
151	        // Record how many existing owners already share this owner's first and last name
152	        // (compared case-insensitively) before this create, fixed at creation time.
153	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
154	        // Assign the customer code '<LAST3>-<NNNN>' from the last name and a global sequence
155	        // equal to one more than the current number of owners, fixed at creation time.
156	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
157	        this.clinicService.saveOwner(owner);
158	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
159	        headers.setLocation(UriComponentsBuilder.newInstance()
160	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
161	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
162	    }
163	
164	    /**
165	     * Canonicalizes the fields of a newly mapped owner on create, in place, so each value is
166	     * persisted and returned in its canonical form. The address is normalized (trimmed, whitespace
167	     * collapsed, upper-cased and common abbreviations expanded, rejecting a value blank after
168	     * normalization with 400), the telephone is normalized to E.164 (rejecting an unformattable
169	     * value with 400), the email is lower-cased, and a missing registration date defaults to the
170	     * server's current date. Canonicalising the address here, before the household checks read it,
171	     * ensures duplicate detection and the shared household id both compare the normalized form.
172	     * Centralising these per-field canonicalizations here keeps {@link #addOwner} focused on the
173	     * duplicate, household and customer-code rules.
174	     *
175	     * @param owner the newly mapped owner to canonicalize
176	     */
177	    private void normalizeOwnerFields(Owner owner) {
178	        // Normalize the address on create so it is stored and returned in canonical form and every
179	        // later comparison (household duplicate detection and the shared household id) uses it.
180	        // A value that is blank after normalization is rejected with 400.
181	        owner.setAddress(addressNormalizer.normalize(owner.getAddress()));
182	        // Normalize the telephone on create so it is stored and returned in canonical E.164 form.
183	        // A value that cannot form a valid E.164 number is rejected with 400.
184	        owner.setTelephone(telephoneNormalizer.normalize(owner.getTelephone()));
185	        // Store the (already syntactically validated) email lower-cased so it is persisted and
186	        // returned in canonical form. A missing email is left untouched.
187	        owner.setEmail(normalizeEmail(owner.getEmail()));
188	        // Default the registration date to the server's current date when the client did not
189	        // supply one, so it is persisted and returned in ISO 'YYYY-MM-DD' form.
190	        if (owner.getRegistrationDate() == null) {
191	            owner.setRegistrationDate(java.time.LocalDate.now());
192	        }
193	    }
194	
195	    /**
196	     * Lower-cases the supplied email address so it is stored and returned in canonical form.
197	     * Bean validation on the request DTO has already guaranteed that any non-null value is a
198	     * syntactically valid address (rejecting anything else with 400).
199	     *
200	     * @param email the email value (may be {@code null})
201	     * @return the lower-cased email, or {@code null} if the input was {@code null}
202	     */
203	    private String normalizeEmail(String email) {
204	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
205	    }
206	
207	    /**
208	     * Builds the customer code '<LAST3>-<NNNN>' for a newly created owner, where LAST3 is the
209	     * upper-cased first three letters of the last name and NNNN is a global 4-digit zero-padded
210	     * sequence equal to one more than the current number of owners (e.g. 'SMI-0007').
211	     *
212	     * @param lastName the owner's last name
213	     * @return the formatted customer code
214	     */
215	    private String nextCustomerCode(String lastName) {
216	        String prefix = lastName.substring(0, Math.min(3, lastName.length()))
217	            .toUpperCase(java.util.Locale.ROOT);
218	        int sequence = this.clinicService.findAllOwners().size() + 1;
219	        return String.format("%s-%04d", prefix, sequence);
220	    }
221	
222	    /**
223	     * Determines whether the given normalized telephone is already used by an existing owner.
224	     * Stored telephones are normalized to E.164 before comparison so values that differ only in
225	     * formatting (spaces, dashes, brackets) or in national vs. international notation are treated
226	     * as the same number.
227	     *
228	     * @param normalizedTelephone the normalized (E.164) telephone to look for
